#pragma once

#include "libs/VehicleSimCore/math/PIDController.h"
#include "libs/VehicleSimCore/math/SlewRateLimiter.h"
#include "libs/VehicleSimCore/math/SpeedProfiler2D.h"
#include "libs/VehicleSimCore/math/Spline2D.h"
#include "libs/VehicleSimCore/math/StanleyController.h"
#include "libs/VehicleSimCore/math/Vec2.h"

namespace vehicle_sim::dynamics {

/// @struct AutopilotOutput
/// @brief Normalized driver actuator demands generated by the trajectory autopilot.
struct AutopilotOutput {
    double normalizedSteer { 0.0 }; ///< Normalized steering input in [-1.0, 1.0].
    double steerAngleRad { 0.0 }; ///< Actuated steering angle in radians.
    double throttle { 0.0 }; ///< Normalized acceleration throttle demand in [0.0, 1.0].
    double brake { 0.0 }; ///< Normalized service braking demand in [0.0, 1.0].
    double targetSpeed { 0.0 }; ///< Target path velocity from profiler in m/s.
    double crossTrackError { 0.0 }; ///< Signed lateral cross-track error in meters.
    double headingError { 0.0 }; ///< Path alignment heading error in radians.
};

/// @class TrajectoryTracker2D
/// @brief Integrated lateral and longitudinal trajectory tracking autopilot.
/// @details Combines front-axle Stanley steering, curvature speed profiling,
/// actuator rate limiting, and PID speed regulation.
class TrajectoryTracker2D {
public:
    /// @brief Default constructor with sports vehicle baseline gains.
    TrajectoryTracker2D() noexcept;

    /// @brief Configures steering, profiling, PID, and steering slew rates.
    /// @param[in] stanleyConfig Tuning parameters for front-axle Stanley controller.
    /// @param[in] profileLimits Vehicle limits for speed profile synthesis.
    /// @param[in] speedGains PID gains for longitudinal speed tracking.
    /// @param[in] maxSteerRate Maximum steering angular velocity in rad/s.
    void configure(const math::StanleyConfig& stanleyConfig, const math::SpeedProfileLimits& profileLimits,
        const math::PIDGains& speedGains, double maxSteerRate) noexcept;

    /// @brief Sets reference trajectory curve and rebuilds the speed profile.
    /// @param[in] spline Pointer to reference spline (must remain valid).
    /// @return True if speed profile was successfully built.
    [[nodiscard]] bool setTrajectory(const math::Spline2D* spline) noexcept;

    /// @brief Resets transient controller integrators, filters, and limiters.
    void reset() noexcept;

    /// @brief Steps the autopilot forward by time step dt.
    /// @param[in] dt Elapsed time step in seconds.
    /// @param[in] cogPosition Vehicle center of gravity world coordinates in meters.
    /// @param[in] headingRad Vehicle heading angle in radians.
    /// @param[in] forwardSpeed Forward longitudinal speed in m/s.
    /// @param[in] yawRate Current vehicle angular yaw velocity in rad/s.
    /// @return Actuator demands ready to dispatch to vehicle dynamics.
    [[nodiscard]] AutopilotOutput update(
        double dt, const math::Vec2& cogPosition, double headingRad, double forwardSpeed, double yawRate) noexcept;

    /// @brief Gets active Stanley controller component.
    /// @return Read-only reference to StanleyController.
    [[nodiscard]] const math::StanleyController& getStanley() const noexcept;

    /// @brief Gets active speed profiler component.
    /// @return Read-only reference to SpeedProfiler2D.
    [[nodiscard]] const math::SpeedProfiler2D& getProfiler() const noexcept;

    /// @brief Gets active speed PID controller component.
    /// @return Read-only reference to PIDController.
    [[nodiscard]] const math::PIDController& getSpeedPid() const noexcept;

private:
    math::StanleyController mStanley {};
    math::SpeedProfiler2D mProfiler {};
    math::PIDController mSpeedPid { 0.4, 0.05, 0.0 };
    math::SlewRateLimiter mSteerLimiter { 2.5 };
    const math::Spline2D* mPath { nullptr };
};

} // namespace vehicle_sim::dynamics
